  /** @nullable */
  port_tags?: (string | null)[] | null;
  sizes?: VehicleSizes;
  dimension?: VehicleDimension;
  emission?: VehicleEmission;
  /** @nullable */
  mass?: number | null;
  /** @nullable */
  mass_hull?: number | null;
  /** @nullable */
  mass_loadout?: number | null;
  /** @nullable */
  mass_total?: number | null;
  /** @nullable */
  cargo_capacity?: number | null;
  /** @nullable */
  ore_capacity?: number | null;
  /** @nullable */
  cargo_grids?: CargoGrid[] | null;
  cargo_limits?: VehicleCargoLimits;
  /** @nullable */
  vehicle_inventory?: number | null;
  /** @nullable */
  inventory_containers?: Container[] | null;
  weapon_storage?: WeaponStorage;
  crew?: VehicleCrew;
  /** @nullable */
  max_medical_tier?: string | null;
  seating?: VehicleSeating;
  /** @nullable */
  health?: number | null;
  /** @nullable */
