  manufacturer?: Manufacturer;
  /** @nullable */
  size_class?: number | null;
  cross_section?: VehicleCrossSection;
  /** @nullable */
  cross_section_max?: number | null;
  /** @nullable */
  is_vehicle?: boolean | null;
  /** @nullable */
