export interface PaginationLinks {
  first?: string;
  last?: string;
  /** @nullable */
  prev?: string | null;
  /** @nullable */
  next?: string | null;
}

export type PaginationMetaLinksItem = {
  /** @nullable */
  url?: string | null;
  label?: string;
  /** @nullable */
  page?: number | null;
  active?: boolean;
};

export interface PaginationMeta {
  current_page?: number;
  /** @nullable */
  from?: number | null;
  last_page?: number;
  links?: PaginationMetaLinksItem[];
  path?: string;
  per_page?: number;
  /** @nullable */
  to?: number | null;
  total?: number;
  valid_relations?: string[];
}

export interface VehicleCollection {
  data: Vehicle[];
  links: PaginationLinks;
  meta: PaginationMeta;
}

export type ErrorErrors = {[key: string]: string[]};

export interface Error {
  message?: string;
  errors?: ErrorErrors;
}

export type LocaleCode = typeof LocaleCode[keyof typeof LocaleCode];


export const LocaleCode = {
  en_EN: 'en_EN',
  de_DE: 'de_DE',
  zh_CN: 'zh_CN',
  fr_FR: 'fr_FR',
} as const;

/**
 * Items per page (alias of `page[size]`). Capped server-side at 50.
 */
export type LimitParameter = number;

/**
 * Page number (alias of `page[number]`).
 */
export type PageParameter = number;

export type PageSizeParameter = number;

export type PageNumberParameter = number;

export type LocaleParameter = LocaleCode;

/**
 * Partial match on vehicle name.
 */
export type FilterNameParameter = string;

export type IncludeParameterItem = typeof IncludeParameterItem[keyof typeof IncludeParameterItem];


export const IncludeParameterItem = {
  shipMatrixVehicle: 'shipMatrixVehicle',
  components: 'components',
  shipmatrixvehiclecomponents: 'shipmatrixvehicle.components',
  hardpoints: 'hardpoints',
  ports: 'ports',
} as const;

/**
 * Comma-separated relations. See `meta.valid_relations`.
 */
export type IncludeParameter = IncludeParameterItem[];

export type ListVehiclesParams = {
  /**
   * Items per page (alias of `page[size]`). Capped server-side at 50.
   * @minimum 1
   * @maximum 50
   */
  limit?: LimitParameter;
  /**
   * Page number (alias of `page[number]`).
   * @minimum 1
   */
  page?: PageParameter;
  /**
   * @minimum 1
   * @maximum 50
   */
  'page[size]'?: PageSizeParameter;
  /** @minimum 1 */
  'page[number]'?: PageNumberParameter;
  /**
   * When set, localized fields (`description`, `type`, `size`, `production_status`, …)
   * are returned as plain strings instead of a locale map.
   */
  locale?: LocaleParameter;
  /** Partial match on vehicle name. */
  'filter[name]'?: FilterNameParameter;
  /** Comma-separated relations. See `meta.valid_relations`. */
  include?: IncludeParameter;
};

